Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='compactasking', at=datetime(2026, 10, 25, 0, 0, 0), actor='assistant', title='Each summary records the version of how its class was asked; a stale summary is asked again and hidden meanwhile', body="Each summary records the version of how its node's class was asked (`compact_ask::Asking`, a `rule_version::Versioned` hashing what each class's log shows on a fixed probe, 2026-10-25), and one asked under an older version, or over a child's summary since replaced, is stale: asked again lowest level first, the owner's nodes first, and while stale an owner's node's summary is shown to no reader (`suzatary secretary digest census` counts them).", rationale='Decided 2026-10-25.', supersedes=()))